import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"工作集","description":"","frontmatter":{"title":"工作集","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/working-set.md","filePath":"cs/working-set.md","lastUpdated":1789023840000}'),h={name:"cs/working-set.md"};function m(C,a,_,E,A,f){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="工作集" tabindex="-1">工作集 <a class="header-anchor" href="#工作集" aria-label="Permalink to &quot;工作集&quot;">​</a></h1><div class="epigraph"><p>程序在时刻 t 的工作集，是过去 Δ 个引用里触及的页集合；驻留集应盖住它，而不是盖住整个虚空间。</p><footer>—— 据 Denning, The Working Set Model for Program Behavior, CACM 1968 整理</footer></div><p><a href="/cs/clock-replace">上一课</a>能在帧之间转圈，却没有说<strong>该给这个进程多少帧</strong>。<a href="/cs/demand-paging">按需调页</a>已用工作集解释「虚大于物仍可跑」，当时是口号。缺口是把 Δ 窗口收成置换与多道的输入：工作集大小 W(t, Δ) 随相位变；时钟指针应优先留下窗口内的页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全局 CLOCK 可能把刚要跑的进程页全部抢走，下一次调度立刻 major 缺页。局部配额若是固定帧数，相位一变就浪费或不足。Denning 的缺口：用近期引用集当「现在必须在内存里的页」。Δ 太大则工作集接近全部虚页；太小则抖动。本课不把 Δ 的最优估计写成一条公式交差。</p><p>本课不引入工作集采样的全部内核计数器。</p><p><span class="marginnote">WSClock：时钟扫描时看「上次使用是否落在 Δ 内」，把 CLOCK 与工作集合并。PFF（缺页频率）用缺页率涨落加减帧，是另一条控制回路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>为进程维护近期页集合（硬件访问位 + 周期性采样，或引用串的软件窗口）。置换时：窗口内的页不当牺牲；窗口外的可以给 CLOCK 扔掉。分配帧时：试图让驻留集 ≥ W(t, Δ)。做不到就不要再提高多道——下一课抖动。预调可以一次装入工作集的邻页，仍属按需的加速，不是改变窗口定义。</p>',9)),(e(),s(p,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REF%5B%22%E5%BC%95%E7%94%A8%E4%B8%B2%22%5D%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%20%CE%94%22%5D%0A%20%20WIN%20--%3E%20WS%5B%22%E5%B7%A5%E4%BD%9C%E9%9B%86%20W%22%5D%0A%20%20WS%20--%3E%20RES%5B%22%E9%A9%BB%E7%95%99%E9%9B%86%E5%BA%94%E8%A6%86%E7%9B%96%20W%22%5D%0A%20%20RES%20--%3E%20CLK%5B%22CLOCK%20%E5%8F%AA%E6%B7%98%E6%B1%B0%E7%AA%97%E5%A4%96%E9%A1%B5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>工作集把局部性从 Cache 课接到多道：CPU 调度看到的「可运行」，隐含「其工作集已在内存」。否则调度只是把缺页从一个进程转到另一个。它不改 <a href="/cs/paging-vm">分页</a> 的翻译，只改帧的归属策略。与公平调度对照：CFS 分的是 CPU 时间；工作集分的是帧。两者同时紧张时，先减多道比先减时间片更对——理由下一课展开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证能精确测量 W：采样有滞后，多线程共享地址空间时窗口是进程级还是线程级，实现各异。也不把工作集当成数据库缓冲池的同义词；那是文件页 Cache 的后课。Δ 与时钟中断频率有关，但不是 jiffies 课。</p><p>后课默认：驻留集应对准工作集。当所有进程的 W 之和超过物理内存，任何置换都会失败，下一课叫抖动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工作集是窗口 Δ 内的页集；驻留应覆盖它。</li><li>WSClock / PFF 是把窗口接到 CLOCK 的控制。</li><li>覆盖失败时的系统行为是抖动课的缺口。</li><li>出处：Denning, <em>CACM</em> 1968；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const S=i(h,[["render",m]]);export{u as __pageData,S as default};
